-- 62 Phoenix: the fire is the emitters' - their `emit_shape` is the bird's
-- own sprite (its outline for the flames, its body for the embers) and the
-- ring's own path - so this only moves the bird: it rises and falls, its
-- wings beat (a squash of its width), and Space gives one great beat.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/62-phoenix.scene"
local captions = true
local bird, ring, status
local t, surge = 0, 0

function init(entity)
    bird = Entity.find_by_name("Phoenix")
    ring = Entity.find_by_name("Ring")
    status = Entity.find_by_name("Status")
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then surge = 1.0 end
    t = t + dt
    surge = math.max(0, surge - dt * 1.2)
    local beat = math.sin(t * (2.2 + surge * 4))
    local y = 20 + 14 * math.sin(t * 0.9) + 30 * surge
    if bird then
        Transform.set_position(bird, 0, y)
        Transform.set_scale(bird, 1.0 + 0.07 * beat + 0.12 * surge, 1.0 - 0.03 * beat)
        Transform.set_rotation(bird, 0.04 * math.sin(t * 0.7))
    end
    if ring then Transform.set_rotation(ring, t * 0.2) end
    if status then UI.set_text(status, surge > 0 and "a great wingbeat" or "fire keeps to the shape it pours from") end
end
